  "青龍蒼": {
    "creator": "sisty",
    "origin": "sisty",
    "year": null,
    "readings": [],
    "videos": [],
    "pitfalls": "sisty说；其他：*技名来源于 “ 青龍 ” 的别称 “ 苍龙 ” 。由于自己的原创技中没有中国风格的技，因此产生了 “ 想要尝试创作！” 的想法，这便是创作的契机。该技的特点在于初始动作前的姿势、初始动作的进入方式以及 “ 龙之构 ” （0:13时的姿势）的轮廓。如果在 “ 龙之构 ” 前的类似 “ 腕十六 ” 的动作能够流畅完成，视觉效果将会更加出色。希望大家一定要挑战一下。（AI翻译+人工修改）青龍の別名である『蒼龍』が技名の由来です。自分のオリジナル技に中国風の技が無くて『作ってみたい！』って思ったのが作成のキッカケでした。 初動前の姿勢・初動の入り・龍の構え（0:13の姿勢）のシルエットが特徴の技です。龍の構え前のデフラワーみたいな動きが滑らかに出来たら見映えが更に増すんじゃ無いかなと思います。 是非チャレンジしてみて下さい。",
    "seriesJa": "青龙",
    "tags": [
      "sisty",
      "青龙系",
      "五圣兽技"
    ]
  },
