  "ゼノモーフ": {
    "creator": "Mizaeru",
    "origin": "Mizaeru",
    "year": null,
    "readings": [
      "Xenomorph",
      "Zenomo-fu"
    ],
    "videos": [],
    "pitfalls": "来自Mizaeru 该技术的特点是忠实再现主题的不规则轨迹和在游戏结束时称为 genetion 的动作。 它是以 1979 年科幻电影《异形》系列中出现的外星生命为主题的。 出现在每个系列中的外星人有不同的名字，尽管他们看起来几乎相同，但他们的名字取自最著名的 Xenomorphs。 这种技术通过每个动作表达了外星人诞生的过程。 首先是レクイエム〈镇魂曲〉之后的动作，然后是ジャックナイフ〈杰克小刀〉反转（右手牢牢地放在背后） 开口部分是鸡蛋开口的图像，从切口清洁的动作是寄生虫（抱脸虫）的印象。好怪哦 可以比作倒 Z 的部分被绘制成只用手腕弹起，这样抱脸虫就会粘在脸上，然后立即将手臂拉到右臀部产卵。好怪哦 寄生虫进入→体的地方，通过胸骨吃东西，在一个固定的地方。好怪哦 营养物质循环并呈圆圈生长。 想象一下胸部破坏者用双手转向左侧的部分吃穿胸骨的那一刻。好怪哦 最后的收获 Geneion 描绘了一次攻击，其中外星人用双嘴刺伤人类的头。；相关信息",
    "seriesJa": null,
    "tags": [
      "ミザエル"
    ]
  },
